"""Cuaderno del estudiante de 8.º básico Matemática: OA 08 (modelación con ecuaciones lineales) y OA 09 (inecuaciones lineales)."""
from __future__ import annotations

from fractions import Fraction as F

from student_content_ma08_lib import L, cx, show
from student_lessons import ex

OA8, OA9 = "MA08 OA 08", "MA08 OA 09"


def ine(a, b, op, c):
    """Solución de a·x + b (op) c como texto «x op valor»; invierte el sentido si a < 0."""
    a, b, c = F(a), F(b), F(c)
    flip = {"<": ">", ">": "<", "≤": "≥", "≥": "≤"}
    r = (c - b) / a
    return f"x {flip[op] if a < 0 else op} {show(r)}"


def cn(q, a, b, op, c, why):
    return ex(q, ine(a, b, op, c), why)


